#include <linux/tracepoint.h>
#include <linux/limits.h>

void handle_syscall_entry(void* ignore, struct pt_regs* regs, long id) {
    // Retrieve the syscall number from the register context
    long syscall_number = pt_regs_SYSCALL(regs);

    // Check if the syscall number is valid and enabled
    if (syscall_number < 0 || syscall_number >= MAX_SYSCALL_NR) {
        return;
    }

    // Get metadata for the syscall
    struct syscall_metadata* metadata = get_syscall_metadata(syscall_number);
    if (!metadata) {
        return;
    }

    // Calculate the size of the trace record
    size_t record_size = sizeof(struct trace_record) + metadata->arg_count * sizeof(struct syscall_arg);
    if (record_size > MAX_TRACE_RECORD_SIZE) {
        return;
    }

    // Align the record size to the required boundary
    size_t aligned_size = ALIGN(record_size, TRACE_RECORD_ALIGNMENT);
    if (aligned_size > MAX_TRACE_RECORD_SIZE) {
        return;
    }

    // Allocate and initialize the trace record
    struct trace_record* record = kmalloc(aligned_size, GFP_KERNEL);
    if (!record) {
        return;
    }

    // Fill the trace record with syscall arguments
    for (int i = 0; i < metadata->arg_count; i++) {
        record->args[i].arg_number = i;
        record->args[i].value = pt_regs_get_arg(regs, i);
    }

    // Submit the trace record to the trace buffer
    trace_submit(record, aligned_size);

    // Free the allocated memory
    kfree(record);
}
